with ranked as (select id, session_id, event_type, page, event_time, duration_sec from (select *, row_number() over (partition by event_type order by event_time nulls last, id) as row_num from web_events) t where row_num = 1) select s.id, s.session_id, s.event_type, s.event_time, s.duration_sec, (select avg(t2.duration_sec) from web_events t2 where t2.session_id = s.session_id) as avg_web_event_duration_sec from ranked s
